//! USB HID report layouts shared by the BUD and Phaze clients.

// Two mouse TLCs on one USB device. Absolute report 1 carries position only;
// relative report 3 owns ALL buttons/wheels, including on the desktop. Thus a
// mode transition never transfers a held button between Windows HID devices.
// Explicit global items in each TLC prevent state leaking from other reports.
pub const MOUSE_REPORT: &[u8] = &[
    0x05, 1, 0x09, 2, 0xa1, 1, 0x85, 1, 0x09, 1, 0xa1, 0, 0x09, 0x30, 0x09, 0x31, 0x15, 0, 0x26,
    0xff, 0x7f, 0x75, 16, 0x95, 2, 0x81, 2, 0xc0, 0xc0, 0x05, 1, 0x09, 2, 0xa1, 1, 0x85, 3, 0x09,
    1, 0xa1, 0, 0x05, 9, 0x19, 1, 0x29, 5, 0x15, 0, 0x25, 1, 0x95, 5, 0x75, 1, 0x81, 2, 0x95, 1,
    0x75, 3, 0x81, 3, 0x05, 1, 0x09, 0x30, 0x09, 0x31, 0x16, 1, 0x80, 0x26, 0xff, 0x7f, 0x75, 16,
    0x95, 2, 0x81, 6, 0x15, 0x81, 0x25, 0x7f, 0x75, 8, 0x95, 1, 0x09, 0x38, 0x81, 6, 0x05, 0x0c,
    0x0a, 0x38, 2, 0x81, 6, 0xc0, 0xc0,
];
